import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const outFile = join(__dirname, "generated-oauth-config.js");

// Outboundly's own registered Google Cloud OAuth client (Section 13.1: one app-owned client
// shared by every install, never a per-user credential). Sourced from env vars set only in the
// build environment -- never committed, since this generated file is gitignored. Local dev
// without these set still works via electron/main.js's `process.env.GOOGLE_CLIENT_ID` override
// path; this file just supplies the shipped default.
const clientId = process.env.GOOGLE_CLIENT_ID ?? "";
const clientSecret = process.env.GOOGLE_CLIENT_SECRET ?? "";

writeFileSync(
  outFile,
  `// Auto-generated by electron/generate-oauth-config.mjs at build time -- do not edit, do not commit.\n` +
    `export const GOOGLE_CLIENT_ID = ${JSON.stringify(clientId)};\n` +
    `export const GOOGLE_CLIENT_SECRET = ${JSON.stringify(clientSecret)};\n`
);

console.log(clientId ? "Wrote OAuth config (client ID present)" : "Wrote empty OAuth config (no env vars set)");
